import{_ as e,o,c as a,ai as n}from"./chunks/framework.jD4ETUAz.js";const u=JSON.parse('{"title":"上市公司公告查询：业绩预告、回购与调研记录","description":"用 AI 助手和 cninfo-mcp 检索巨潮资讯网的上市公司公告：按公司、标题关键字、26 个公告分类、板块和日期筛选，支持全市场检索业绩预告，以及查询投资者关系活动记录表。","frontmatter":{"title":"上市公司公告查询：业绩预告、回购与调研记录","description":"用 AI 助手和 cninfo-mcp 检索巨潮资讯网的上市公司公告：按公司、标题关键字、26 个公告分类、板块和日期筛选，支持全市场检索业绩预告，以及查询投资者关系活动记录表。","article":true,"date":"2026-11-16T00:00:00.000Z","editLink":false,"head":[["link",{"rel":"canonical","href":"https://youhaozhao.github.io/cninfo-mcp/guides/search-announcements"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"cninfo-mcp"}],["meta",{"property":"og:title","content":"上市公司公告查询：业绩预告、回购与调研记录 | cninfo-mcp"}],["meta",{"property":"og:description","content":"用 AI 助手和 cninfo-mcp 检索巨潮资讯网的上市公司公告：按公司、标题关键字、26 个公告分类、板块和日期筛选，支持全市场检索业绩预告，以及查询投资者关系活动记录表。"}],["meta",{"property":"og:url","content":"https://youhaozhao.github.io/cninfo-mcp/guides/search-announcements"}],["meta",{"property":"og:image","content":"https://youhaozhao.github.io/cninfo-mcp/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"上市公司公告查询：业绩预告、回购与调研记录 | cninfo-mcp"}],["meta",{"name":"twitter:description","content":"用 AI 助手和 cninfo-mcp 检索巨潮资讯网的上市公司公告：按公司、标题关键字、26 个公告分类、板块和日期筛选，支持全市场检索业绩预告，以及查询投资者关系活动记录表。"}],["meta",{"name":"twitter:image","content":"https://youhaozhao.github.io/cninfo-mcp/og.png"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"首页\\",\\"item\\":\\"https://youhaozhao.github.io/cninfo-mcp/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"使用指南\\",\\"item\\":\\"https://youhaozhao.github.io/cninfo-mcp/guides/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"上市公司公告查询：业绩预告、回购与调研记录\\",\\"item\\":\\"https://youhaozhao.github.io/cninfo-mcp/guides/search-announcements\\"}]},{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://youhaozhao.github.io/cninfo-mcp/guides/search-announcements#article\\",\\"headline\\":\\"上市公司公告查询：业绩预告、回购与调研记录\\",\\"description\\":\\"用 AI 助手和 cninfo-mcp 检索巨潮资讯网的上市公司公告：按公司、标题关键字、26 个公告分类、板块和日期筛选，支持全市场检索业绩预告，以及查询投资者关系活动记录表。\\",\\"inLanguage\\":\\"zh-CN\\",\\"url\\":\\"https://youhaozhao.github.io/cninfo-mcp/guides/search-announcements\\",\\"mainEntityOfPage\\":\\"https://youhaozhao.github.io/cninfo-mcp/guides/search-announcements\\",\\"image\\":\\"https://youhaozhao.github.io/cninfo-mcp/og.png\\",\\"datePublished\\":\\"2026-11-16T00:00:00.000Z\\",\\"dateModified\\":\\"2026-11-16T07:46:57.000Z\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"youhaozhao\\",\\"url\\":\\"https://github.com/youhaozhao\\"},\\"publisher\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"youhaozhao\\",\\"url\\":\\"https://github.com/youhaozhao\\"},\\"isPartOf\\":{\\"@id\\":\\"https://youhaozhao.github.io/cninfo-mcp/#website\\"},\\"about\\":{\\"@id\\":\\"https://youhaozhao.github.io/cninfo-mcp/#software\\"}}]}"]]},"headers":[],"relativePath":"guides/search-announcements.md","filePath":"guides/search-announcements.md","lastUpdated":1794815217000}'),i={name:"guides/search-announcements.md"};function c(d,t,r,h,p,s){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="上市公司公告查询-业绩预告、回购与调研记录" tabindex="-1">上市公司公告查询：业绩预告、回购与调研记录 <a class="header-anchor" href="#上市公司公告查询-业绩预告、回购与调研记录" aria-label="Permalink to &quot;上市公司公告查询：业绩预告、回购与调研记录&quot;">​</a></h1><p>想知道一家公司最近发了什么公告，或者过去一个月全市场有哪些公司发布了业绩预告，都可以直接问 AI 助手。cninfo-mcp 的 <code>search_announcements</code> 工具在巨潮资讯网上检索公告，默认按披露时间从新到旧返回。</p><p>下面的示例结果来自 2026 年 11 月的实际查询。</p><h2 id="查一家公司的公告" tabindex="-1">查一家公司的公告 <a class="header-anchor" href="#查一家公司的公告" aria-label="Permalink to &quot;查一家公司的公告&quot;">​</a></h2><blockquote><p>宁德时代今年有哪些回购相关的公告？</p></blockquote><p>AI 会用公司名和标题关键字“回购”检索，得到 12 条结果，最新的几条是：</p><table tabindex="0"><thead><tr><th>披露日期</th><th>标题</th></tr></thead><tbody><tr><td>2026-11-02</td><td>关于回购公司A股股份的进展公告</td></tr><tr><td>2026-10-08</td><td>关于回购公司A股股份的进展公告</td></tr><tr><td>2026-09-11</td><td>关于首次回购公司A股股份的公告</td></tr></tbody></table><p>每条结果都带有 PDF 地址，可以接着让 AI 读正文：</p><blockquote><p>读一下首次回购那份公告，回购了多少股、均价是多少？</p></blockquote><p>一次也可以查多家公司（最多 10 家）：</p><blockquote><p>贵州茅台和五粮液今年的权益分派公告有哪些？</p></blockquote><h2 id="全市场检索-谁发了业绩预告" tabindex="-1">全市场检索：谁发了业绩预告 <a class="header-anchor" href="#全市场检索-谁发了业绩预告" aria-label="Permalink to &quot;全市场检索：谁发了业绩预告&quot;">​</a></h2><p>不指定公司，就是在全市场范围内检索，可以按公告分类、板块和日期筛选。</p><blockquote><p>过去一个月创业板有哪些公司发布了业绩预告？</p></blockquote><p>这个问题对应的条件是：分类“业绩预告”，板块“创业板”，日期 2026-10-16 至 2026-11-16。查询返回 6 条公告，例如长川科技、航天智造、申昊科技的前三季度业绩预告。</p><p>可以筛选的板块有：</p><table tabindex="0"><thead><tr><th>板块</th><th>取值</th><th>板块</th><th>取值</th></tr></thead><tbody><tr><td>沪市全部</td><td><code>sh</code></td><td>深市全部</td><td><code>sz</code></td></tr><tr><td>沪主板</td><td><code>shmb</code></td><td>深主板</td><td><code>szmb</code></td></tr><tr><td>科创板</td><td><code>shkcp</code></td><td>创业板</td><td><code>szcy</code></td></tr><tr><td>北交所</td><td><code>bj</code></td><td></td><td></td></tr></tbody></table><p>再举几个全市场检索的问法：</p><blockquote><p>本周科创板有哪些公司发布了风险提示公告？</p></blockquote><blockquote><p>上个月北交所有哪些公司披露了股权激励相关的公告？</p></blockquote><blockquote><p>11 月以来沪主板有哪些公司发布了可转债公告？</p></blockquote><h2 id="公告分类" tabindex="-1">公告分类 <a class="header-anchor" href="#公告分类" aria-label="Permalink to &quot;公告分类&quot;">​</a></h2><p>公告分类一共 26 个，覆盖定期报告、业绩预告、权益分派、董事会和股东会、股权激励、增发配股、可转债、股权变动、补充更正、澄清致歉、风险提示、退市等。提问时用中文说法就可以，AI 会换成对应的分类。常用的几个：</p><table tabindex="0"><thead><tr><th>想找的内容</th><th>分类</th></tr></thead><tbody><tr><td>业绩预告、业绩快报</td><td>业绩预告</td></tr><tr><td>分红派息、送转</td><td>权益分派</td></tr><tr><td>股东增减持、权益变动</td><td>股权变动</td></tr><tr><td>定增</td><td>增发</td></tr><tr><td>股票交易异常波动、风险提示</td><td>风险提示</td></tr><tr><td>年报或季报的更正</td><td>补充更正</td></tr></tbody></table><p>完整的分类表见<a href="/cninfo-mcp/reference/tools#search-announcements">工具与配置参考</a>。</p><div class="info custom-block"><p class="custom-block-title">分类和关键字的区别</p><p>分类是巨潮资讯网给公告打的标签，关键字匹配的是公告标题。回购这类没有单独分类的主题，用标题关键字来找。分类只适用于沪、深、北交所的公告，港股公告请用关键字检索。</p></div><h2 id="调研记录-投资者关系活动记录表" tabindex="-1">调研记录：投资者关系活动记录表 <a class="header-anchor" href="#调研记录-投资者关系活动记录表" aria-label="Permalink to &quot;调研记录：投资者关系活动记录表&quot;">​</a></h2><p>机构调研纪要披露在“投资者关系活动记录表”里，在巨潮资讯网上属于另一个栏目，同样可以检索。</p><blockquote><p>宁德时代最近几次机构调研都聊了什么？</p></blockquote><p>AI 会把检索范围切换到投资者关系栏目，找到 37 条记录，最近的三份是 2026 年 10 月 20 日、7 月 24 日和 4 月 15 日的活动记录表，然后读取正文并归纳。</p><p>这个栏目下有四类记录：调研活动、路演活动、媒体采访和管理制度。</p><h2 id="日期、排序和翻页" tabindex="-1">日期、排序和翻页 <a class="header-anchor" href="#日期、排序和翻页" aria-label="Permalink to &quot;日期、排序和翻页&quot;">​</a></h2><ul><li><strong>日期</strong>：起止日期都包含在内，按北京时间计算。问题里说“过去一个月”“今年以来”，AI 会换算成具体日期。</li><li><strong>排序</strong>：默认从新到旧，也可以要求从旧到新。</li><li><strong>数量</strong>：一次默认返回 30 条，最多 200 条。结果里带有命中总数，还有更多时 AI 可以继续翻页。</li></ul><h2 id="检索范围与限制" tabindex="-1">检索范围与限制 <a class="header-anchor" href="#检索范围与限制" aria-label="Permalink to &quot;检索范围与限制&quot;">​</a></h2><ul><li>覆盖沪、深、北交所上市公司（含 B 股）的公告和港股公告；基金、债券可以按代码检索公告。</li><li>公告按<strong>标题</strong>关键字检索，不支持跨公告的全文检索。要在一份公告的正文里找内容，让 AI 读取这份文档并在文档内按关键字定位。</li><li>结果里的 <code>complete</code> 为 <code>false</code> 时，说明部分分页没有取到，此时的清单并不完整。</li></ul><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li>读公告和报告的正文：<a href="/cninfo-mcp/guides/read-annual-reports-with-ai">用 AI 读年报</a></li><li>把公告保存到本地：让 AI 按地址下载（<code>download_documents</code>），保存位置见<a href="/cninfo-mcp/guides/download-annual-reports">年报下载</a></li><li>全部参数：<a href="/cninfo-mcp/reference/tools#search-announcements">工具与配置参考</a></li></ul>',37)])])}const m=e(i,[["render",c]]);export{u as __pageData,m as default};
